/* Faction background is a read-only page. No lore text enters roster or rule records. */
(function(){'use strict';
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),L=(en,ko,tag='span')=>`<${tag} data-i18n-en="${E(en)}" data-i18n-ko="${E(ko)}">${E(en)}</${tag}>`,account=()=>window.AccountParity?.account?.id||'';
const book='<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M12 5v15M12 5C8 2 3 3 3 3v16s5-1 9 1c4-2 9-1 9-1V3s-5-1-9 2Z"/></svg>';
let active=null;
function resolve(g){if(!g||String(g.edition).toLowerCase()!=='n26'||g.customGangTypeId||g.custom_gang_type_id||g.isCustomGang)return null;const typeId=g.gangTypeId||g.gang_type_id;if(typeId&&!(window.RULES_DATA?.gangTypes||[]).some(t=>t.id===typeId&&t.source_verified))return null;const type=window.MMVerifiedRules?.gangType(g),entry=window.MMGangLoreData?.[type?.id];return type?.source_verified&&entry?{type,entry}:null;}
function current(){const g=typeof gang==='function'?gang():null;return active&&data.view==='gang'&&g?.id===active.gangId&&account()===active.account&&resolve(g)?.type.id===active.typeId?g:null;}
function headingName(type){return L(type.name,type.name_ko||window.UKI18n?.name(type.name)||type.name);}
const groups={history:['History & origins','역사·기원'],culture:['Culture & belief','문화·신앙'],people:['People & legends','인물·전설'],stories:['Events & stories','사건·이야기'],places:['Places & journeys','거점·여정'],society:['Life & society','생활·사회']};
function sourceType(src){const host=new URL(src.url).hostname;if(src.kind==='wiki'||host.endsWith('lexicanum.com'))return ['Fan wiki','팬 위키'];if(src.kind==='fan-summary'||host==='gall.dcinside.com')return ['Fan summary','팬 요약'];if(src.kind==='fiction-catalog'||host.endsWith('blacklibrary.com'))return ['Fiction catalogue','소설 소개'];if(src.kind==='official-setting'||host==='necromunda.com')return ['Official setting','공식 세계관'];return ['Official article / publication','공식 기사·간행물'];}
function sourceLink(src){return `<a href="${E(src.url)}" target="_blank" rel="noopener noreferrer">${L(...src.title)} ↗</a><small class="gl-source-kind">${L(...sourceType(src))}${src.access==='search-excerpt'?' · '+L('Search excerpt only','검색 색인의 소개만 확인'):''}</small>`;}
function chapterBody(ch){const paragraphs=ch.paragraphs||[ch.text],sources=(ch.sourceIds||[]).map(id=>window.MMGangLoreSources[id]).filter(Boolean);return paragraphs.map(text=>L(...text,'p')).join('')+(sources.length?`<aside class="gl-chapter-sources" aria-label="Sources and reading" data-i18n-en-aria-label="Sources and reading" data-i18n-ko-aria-label="출처와 더 읽을 자료"><strong>${L('Sources & further reading','출처·더 읽을 자료')}</strong>${sources.map(src=>`<div>${sourceLink(src)}</div>`).join('')}</aside>`:'');}
function worldBackground(){const chapters=window.MMGangLoreResearch?.worldChapters||[];if(!chapters.length)return '';return `<details class="gl-world" id="gl-world" data-lore-world${active.worldOpen?' open':''}><summary>${L('Understanding Necromunda: shared background','네크로문다를 이해하는 공통 배경')} <small>${chapters.length}</small></summary><div class="gl-world-topics">${chapters.map((ch,i)=>`<details class="gl-world-topic" data-lore-world-topic="${i}"${active.worldSections.has(i)?' open':''}><summary>${L(...ch.title)}</summary><div class="gl-chapter-body">${chapterBody(ch)}</div></details>`).join('')}</div><a class="gl-research-link" href="/chronicle.html">${L('Read the Necromunda chronicle','네크로문다 연대기 읽기')} →</a></details>`;}
function page(g){const{type,entry}=resolve(g),image=window.MMGangPortrait?.generatedPortraitAssets?.[type.name==='Venator Gangs'?'Venators':type.name]||'',chapters=entry.chapters;
 return `<article class="gl-page" data-lore-type="${E(type.id)}"><div class="gl-page-top"><button class="gl-back" type="button" data-lore-action="back">← ${L('Back to my gang','내 갱으로 돌아가기')}</button><span class="gl-eyebrow">${L('FACTION ARCHIVE','팩션 아카이브')}</span></div>
 <header class="gl-hero">${image?`<div class="gl-portrait"><img src="${E(image)}" alt="" width="220" height="220"></div>`:''}<div class="gl-hero-copy"><p class="gl-roster-name" data-user-text>${E(g.name)}</p><h1 tabindex="-1">${headingName(type)}</h1><p class="gl-tagline">${L(...entry.tagline)}</p>${L(...entry.summary,'p')}<div class="gl-meta"><span>${L(chapters.length+' topics',chapters.length+'개 주제')}</span><span>${L(entry.sources.length+' sources',entry.sources.length+'개 출처')}</span>${entry.researchedOn?`<span>${L('Updated','보강일')} ${E(entry.researchedOn)}</span>`:''}</div><div class="gl-reading-links"><button class="btn small" type="button" data-lore-read="rules">${L('Faction rules','팩션 룰')}</button><button class="btn small" type="button" data-lore-read="guide">${L('Beginner guide','초보자 가이드')}</button></div></div></header>
 <dl class="gl-facts">${entry.facts.map(([en,ko,valueEn,valueKo])=>`<div><dt>${L(en,ko)}</dt><dd>${L(valueEn,valueKo)}</dd></div>`).join('')}</dl>
 ${worldBackground()}
 <div class="gl-layout"><nav class="gl-contents" aria-label="Lore contents" data-i18n-en-aria-label="Lore contents" data-i18n-ko-aria-label="로어 목차"><strong>${L('In this story','이야기 목차')}</strong><ol>${chapters.map((ch,i)=>`<li><button type="button" data-lore-jump="${i}" aria-controls="gl-chapter-${i}"><small>${String(i+1).padStart(2,'0')}</small>${L(...ch.title)}</button></li>`).join('')}</ol><p>${L('Choose a subject to open it.','주제를 누르면 해당 내용이 펼쳐집니다.')}</p></nav>
 <div class="gl-reading"><div class="gl-reading-heading"><h2>${L('Background & culture','배경과 문화')}</h2><button class="gl-expand" type="button" data-lore-action="expand" aria-expanded="${active.sections.size===chapters.length}">${active.sections.size===chapters.length?L('Collapse all','모두 접기'):L('Expand all','모두 펼치기')}</button></div>
 <div class="gl-chapters">${chapters.map((ch,i)=>`<details class="gl-chapter" id="gl-chapter-${i}" data-lore-chapter="${i}"${active.sections.has(i)?' open':''}><summary><span class="gl-chapter-number">${String(i+1).padStart(2,'0')}</span><div class="gl-chapter-title">${ch.group?`<small>${L(...groups[ch.group])}</small>`:''}<h3>${L(...ch.title)}</h3></div><span class="gl-chevron" aria-hidden="true"></span></summary><div class="gl-chapter-body">${chapterBody(ch)}</div></details>`).join('')}</div>
 <details class="gl-sources"><summary>${L('Background reading & sources','배경 자료·참고 출처')} <span>${entry.sources.length}</span></summary><p>${L('Independent reading notes from official publications and clearly labelled secondary sources. Lexicanum is a fan wiki whose footnotes point to original books; a wiki reference is not a claim that the original book was read. Fiction catalogue notes cover introductions, not entire novels. Game effects remain in Faction Rules.','공식 자료와 유형을 표시한 2차 자료를 바탕으로 정리한 해설입니다. 렉시카눔은 원전 목록이 있는 팬 위키이며, 위키의 인용을 확인한 것과 해당 원전을 직접 읽은 것은 구분합니다. 소설 소개는 작품 안내 범위이며 소설 전체의 요약이 아닙니다. 실제 게임 효과는 팩션 룰에서 확인하세요.')}</p><ul>${entry.sources.map(src=>`<li>${sourceLink(src)}<small>${E(src.publisher||'Warhammer Community')}${src.checkedOn?' · '+E(src.checkedOn):''}</small>${src.note?.length?`<small>${Array.isArray(src.note)?L(...src.note):E(src.note)}</small>`:''}</li>`).join('')}</ul><p class="gl-attribution">${L('Wiki references credit the linked Lexicanum articles and their contributors. These notes combine and paraphrase sources; they do not reproduce the articles.','위키 참고 자료의 저자는 링크된 렉시카눔 문서의 기여자들입니다. 본문은 여러 자료를 대조하여 새로 정리한 해설이며 해당 문서를 그대로 전재한 것이 아닙니다.')}</p><a class="gl-research-link" href="/reports/lore-research-review.html">${L('Research coverage, changes & access notes','보강 내역·출처 확인 범위 보기')} →</a></details>
 <footer class="gl-reading-footer"><span>${L('Setting background · For game effects, open Faction Rules','세계관 배경 · 게임 효과는 팩션 룰에서 확인')}</span><button class="gl-back" type="button" data-lore-action="back">← ${L('Back to my gang','내 갱으로 돌아가기')}</button></footer></div></div></article>`;
}
function finish(){if(!active)return;const previous=active;active=null;render();const trigger=document.querySelector('[data-gang-lore]');trigger?.focus({preventScroll:true});window.scrollTo?.({top:previous.scroll,behavior:'instant'});}
function open(g=typeof gang==='function'?gang():null,{push=true}={}){const resolved=resolve(g);if(!resolved||data.view!=='gang'||g?.id!==gang()?.id||document.querySelector('.modal-bg'))return false;if(current()){window.MMRuleReference?.close();return true;}window.MMRuleReference?.close();active={gangId:g.id,typeId:resolved.type.id,account:account(),scroll:window.scrollY||0,sections:new Set(),worldOpen:false,worldSections:new Set()};if(push)history.pushState({...history.state,ukGangLore:{gangId:g.id,account:account()}},'',location.pathname+location.search+'#gang-lore');render();window.scrollTo?.({top:0,behavior:'instant'});document.querySelector('.gl-hero h1')?.focus({preventScroll:true});return true;}
function close(){if(!active)return false;if(history.state?.ukGangLore?.gangId===active.gangId){history.back();return true;}finish();return true;}
function syncExpand(){const host=document.querySelector('.gl-page'),button=host?.querySelector('[data-lore-action=expand]');if(!button||!active)return;const all=active.sections.size===host.querySelectorAll('[data-lore-chapter]').length;button.setAttribute('aria-expanded',String(all));button.innerHTML=all?L('Collapse all','모두 접기'):L('Expand all','모두 펼치기');window.UKI18n?.refresh(button);}
const previousTop=gangTop;gangTop=function(g){const html=previousTop.apply(this,arguments);if(!resolve(g))return html;return html.replace('<div class="entity-actions main-actions">',`<div class="entity-actions main-actions"><button class="btn small gl-entry-button" type="button" data-gang-lore>${book}${L('Gang lore','갱 배경·로어')}</button>`);};
const previousPage=gangPage;gangPage=function(){const g=current();return g?page(g):previousPage.apply(this,arguments);};
const previousRender=render;render=function(...args){if(active&&!current()){active=null;const marker=history.state?.ukGangLore;if(marker){const state={...history.state};delete state.ukGangLore;history.replaceState(state,'',location.pathname+location.search);}}return previousRender.apply(this,args);};
window.addEventListener('click',e=>{const b=e.target.closest?.('[data-gang-lore],[data-lore-action],[data-lore-jump],[data-lore-read]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();if(b.hasAttribute('data-gang-lore'))return open();const g=current();if(!g)return;if(b.dataset.loreAction==='back')return close();if(b.dataset.loreAction==='expand'){const rows=[...document.querySelectorAll('[data-lore-chapter]')],expanded=rows.every(el=>el.open);for(const row of rows){row.open=!expanded;if(expanded)active.sections.delete(Number(row.dataset.loreChapter));else active.sections.add(Number(row.dataset.loreChapter));}syncExpand();return;}if(b.hasAttribute('data-lore-jump')){const chapter=document.querySelector('[data-lore-chapter="'+b.dataset.loreJump+'"]');if(chapter){chapter.open=true;active.sections.add(Number(b.dataset.loreJump));syncExpand();chapter.scrollIntoView?.({block:'start',behavior:'instant'});chapter.querySelector('summary')?.focus({preventScroll:true});}return;}if(b.hasAttribute('data-lore-read'))b.focus({preventScroll:true});if(b.dataset.loreRead==='rules')window.MMGangGuide?.openFaction(g);else if(b.dataset.loreRead==='guide')window.MMGangGuide?.open(g);},true);
document.addEventListener('toggle',e=>{const node=e.target;if(current()&&node.isConnected){if(node.matches('[data-lore-world]'))active.worldOpen=node.open;if(node.matches('[data-lore-world-topic]')){const index=Number(node.dataset.loreWorldTopic);if(node.open)active.worldSections.add(index);else active.worldSections.delete(index);}}if(!current()||!node.isConnected||!node.matches?.('[data-lore-chapter]'))return;const index=Number(node.dataset.loreChapter);if(node.open)active.sections.add(index);else active.sections.delete(index);syncExpand();},true);
window.addEventListener('popstate',()=>{const marker=history.state?.ukGangLore;if(active&&marker?.gangId!==active.gangId)return finish();if(!active&&marker?.account===account()&&marker?.gangId===gang()?.id&&data.view==='gang')open(gang(),{push:false});});
window.MMGangLore={resolve,open,close,get isOpen(){return !!current();}};
})();
